package com.nativeimage;

import android.net.Uri;

import androidx.annotation.NonNull;

import android.util.Log;
import android.widget.ImageView;

import com.bumptech.glide.Glide;
import com.facebook.react.uimanager.ReactStylesDiffMap;
import com.facebook.react.uimanager.SimpleViewManager;
import com.facebook.react.uimanager.StateWrapper;
import com.facebook.react.uimanager.ThemedReactContext;
import com.facebook.react.uimanager.annotations.ReactProp;
import com.makeramen.roundedimageview.RoundedImageView;
import android.graphics.Color;
import java.io.File;
import static android.os.Environment.getExternalStoragePublicDirectory;
import android.os.Environment;
import java.util.Timer;
import java.util.TimerTask;
import androidx.annotation.NonNull;
import androidx.annotation.Nullable;
import com.facebook.react.bridge.ReadableMap;

public class NativeImageViewManager extends SimpleViewManager<CustomImageView> {
  public static final String REACT_CLASS = "NativeImageView";
  ThemedReactContext reactContext;
  String url;

  @Override
  @NonNull
  public String getName() {
    return REACT_CLASS;
  }

  @Override
  @NonNull
  public CustomImageView createViewInstance(ThemedReactContext reactContext) {
    this.reactContext = reactContext;

    return new CustomImageView(reactContext);
  }

  @ReactProp(name = "source")
  public void setSource(CustomImageView image, ReadableMap source) {
    this.url = source.getString("uri");
    Log.i("datadata","hello "+source.getString("uri"));
    image.setScaleType(ImageView.ScaleType.CENTER_CROP);
    image.setBackgroundColor(Color.TRANSPARENT);

    setImage(image,source.getString("uri"));
  }

  @ReactProp(name = "radius")
  public void setRadius(CustomImageView image, String radius) {
    image.setCornerRadius(Float.parseFloat(radius));
  }

  @Override
  protected void onAfterUpdateTransaction(@NonNull CustomImageView view) {
    super.onAfterUpdateTransaction(view);
    setImage(view,url);
  }

  @Override
  public void updateProperties(@NonNull CustomImageView viewToUpdate, ReactStylesDiffMap props) {
    super.updateProperties(viewToUpdate, props);
    setImage(viewToUpdate,url);
  }

  private void setImage(CustomImageView image, String source){
    if(source==null){
      return;
    }
    if (source.startsWith("http")) {
      Glide.with(image).load(source).into(image);
    } else{
      if(source.startsWith("file://")){
        source = source.replace("file://","");
      }
      Log.i("datadata",new File(source).exists()+"");
      source =source.replace(" ", "\\ ");
      image.setImageURI(Uri.fromFile(new File(source)));


    }
  }
}
